-- Test specs generated by tdd-agent while a Request is executing (docs/integrate/TDD-REQ-TESTSPEC-001). One row per attempt; the row with
-- is_current = 1 is the one the screen shows. Nothing here is read by the code-execution lane: the two lanes share only the trigger.
CREATE TABLE request.request_test_spec_runs (
    id UUID PRIMARY KEY,
    tenant_id UUID NOT NULL,
    request_id UUID NOT NULL REFERENCES request.requests(id),
    attempt INT NOT NULL DEFAULT 1,
    status TEXT NOT NULL CHECK (status IN ('pending','starting','running','completed','blocked','failed','skipped','cancelled')),
    reason_code TEXT NOT NULL DEFAULT '',
    reason_message TEXT NOT NULL DEFAULT '',
    context_mode TEXT NOT NULL DEFAULT '',
    context_ref TEXT NOT NULL DEFAULT '',
    context_sha256 TEXT NOT NULL DEFAULT '',
    tdd_run_id TEXT NOT NULL DEFAULT '',
    feature TEXT NOT NULL DEFAULT '',
    summary JSONB NOT NULL DEFAULT '{}'::jsonb,
    started_by UUID NULL,
    started_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    finished_at TIMESTAMPTZ NULL,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    -- 1 for the current attempt, NULL once superseded: NULLs never collide, so the unique index allows one current row per Request.
    is_current SMALLINT NULL CHECK (is_current = 1),
    superseded_at TIMESTAMPTZ NULL,
    lease_owner TEXT NOT NULL DEFAULT '',
    lease_until TIMESTAMPTZ NOT NULL DEFAULT '2000-01-01'
);

CREATE UNIQUE INDEX request_test_spec_runs_one_current ON request.request_test_spec_runs (tenant_id, request_id, is_current);
CREATE INDEX request_test_spec_runs_history ON request.request_test_spec_runs (tenant_id, request_id, attempt DESC);
CREATE INDEX request_test_spec_runs_active ON request.request_test_spec_runs (status, updated_at) WHERE is_current = 1 AND status IN ('pending','starting','running');

ALTER TABLE request.request_test_spec_runs ENABLE ROW LEVEL SECURITY;
ALTER TABLE request.request_test_spec_runs FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON request.request_test_spec_runs
    USING (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid)
    WITH CHECK (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid);

-- The reconcile pass picks candidates across tenants (relay access, read only); the lease taken per row under its own tenant keeps replicas apart.
CREATE POLICY relay_scan ON request.request_test_spec_runs
    AS PERMISSIVE FOR SELECT
    USING (current_setting('app.relay', true) = 'on');
